/* Types */
/**
 *  账户变了（选定服务器 / 登录 / 退出 / 等浏览器 / 收到链接）。载荷是**全量**状态：
 *  主窗与设置窗各自订阅同一事件、读同一份 Rust 状态，不各自推导。
 */
export type AccountChanged = {
	state: AccountStateDto,
};

/**  登录到了哪一步。 */
export type AccountPhaseDto = { phase: "signed_out" } |
/**  等用户在浏览器里批准（设备码在 Rust 里轮询，前端只显示与取消）。 */
{ phase: "awaiting_browser"; user_code: string; verification_uri: string } |
/**
 *  登录撞上了这个账户的设备上限（纵切 3 C5）：选一台移除即接着登录（密码类原样重发，设备码接着
 *  轮询同一个配对）。令牌与要重发的请求只在 Rust 里，这里只有上限与设备列表。
 */
{ phase: "device_limit"; limit: DeviceLimitDto } |
/**  已登录。`profile` 读不出来时为 `None`（会话在、档案缓存丢了，界面不编邮箱）。 */
{ phase: "signed_in"; profile: ProfileDto | null };

export type AccountServerDto = {
	origin: string,
	display_name: string | null,
	kind: ServerKind,
};

/**  账户全量状态（`account://changed` 每次推它）。 */
export type AccountStateDto = {
	/**  当前（已登录）或上一次（未登录）的服务器；`None` = 从未登录过。 */
	server: AccountServerDto | null,
	phase: AccountPhaseDto,
	incoming_link: IncomingLinkDto | null,
};

export type ActiveTagDto = {
	tag: string,
	count: number,
};

export type AnchorKeysDto = {
	/**  完整 64 位 hex 按 4 字符分组（[`group_hex`]；**不是**短指纹）。 */
	lease_pubkey: string,
	catalog_pubkey: string,
	/**  信息性参考，不参与判定（见 [`PinnedAnchor::deployment_id`]）。 */
	deployment_id: string,
};

export type AnswerMetaDto = {
	segments: AnswerSegmentDto[],
	sources: RetrievalSourceDto[],
	grounding_outcome: GroundingOutcome,
};

export type AnswerSegmentDto = {
	kind: AnswerSegmentKind,
	markdown: string,
};

/**  回答中一段内容的依据类别。终局只由 Rust 归类，前端不从 Markdown 猜测。 */
export type AnswerSegmentKind = "knowledge_evidence" | "model_supplement";

/**  与状态对应的主按钮（ADR-168 ①）。 */
export type AppActionDto = "install" | "open" | "enable" | "repair" | "update" | "leave_strict_local";

/**
 *  启动快照（PRD-14-066）：主窗首帧需要的几份事实**一次**取回——此前外观、引导门控、
 *  概览门控、状态栏各自读一遍全量设置，同一份数据在启动期跨进程走了四趟。
 */
export type AppBootstrapDto = {
	onboarding: OnboardingStateDto,
	vault: VaultStatusDto,
	settings: SettingSpecDto[],
};

/**
 *  应用的一个组件（一件第三方程序）。默认视图不列它们，只在「开源组件与许可证」二级页出现
 *  （ADR-168 ⑤）。
 */
export type AppComponentDto = {
	/**  组件 id（`yt_dlp` / `js_runtime` / `ffmpeg`，与外部工具同一个词表）。 */
	id: string,
	need: ComponentNeedDto,
	presence: ComponentPresenceDto,
	/**  上游项目的许可证（SPDX）。 */
	license: string,
	/**  上游项目主页（不带协议）。 */
	source: string,
	/**
	 *  在用那一份的版本：只有 Lunarca 下载的那份知道（记在旁文件里）；用户自己装的不去跑它
	 *  探版本（yt-dlp 一次要 8 秒），为 `None`。
	 */
	version: string | null,
	/**  在用那一份的路径（没找到为 `None`）。 */
	path: string | null,
	/**  上一次「检查更新」说 Lunarca 下载的这一份有新版（ADR-168 ⑧）。 */
	update_available: boolean,
	/**  下载这件时 `model://download-progress` 里的 id（能代装的才有；更新时按钮上的进度据此认领）。 */
	progress_id: string | null,
};

/**  一方应用贡献的入口种类（详情页「启用后会多出」）。 */
export type AppContributionDto = "space" | "editor_actions" | "templates" | "windows" | "settings" | "prompts" | "link_import";

/**  安装计划里要下载的一件组件。 */
export type AppDownloadDto = {
	/**  组件 id（原样交回 `app_install` 核对）。 */
	id: string,
	/**  上游来源（仓库地址，不带协议）。 */
	source: string,
	/**  典型下载体积（字节，约数）。 */
	approx_download_bytes: number | null,
	/**  典型磁盘占用（字节，约数）。 */
	approx_disk_bytes: number | null,
	/**  这一件下载时 `model://download-progress` 事件里的 id（按钮上的进度据此认领）。 */
	progress_id: string,
};

/**  「应用」页的一行 / 详情页的数据。 */
export type AppDto = {
	/**  稳定 id（`apps://<id>`、文案键 `apps:<id>.*`）。 */
	id: string,
	/**  此刻是否生效（已安装 ∧ 已启用）：入口露不露出来只看它。 */
	enabled: boolean,
	/**  装了没有（含暂时停用）。 */
	installed: boolean,
	state: AppLifecycleDto,
	/**  主按钮。 */
	action: AppActionDto,
	/**  已经能用、但因推荐组件不在而受限：那几件组件的 id。 */
	limited_by: string[],
	/**  版本（一方应用 = 客户端版本）。 */
	version: string,
	developer: string,
	/**  许可证（SPDX）。 */
	license: string,
	/**
	 *  占用空间（字节）：已安装时是 Lunarca 下载的组件实占，未安装时是安装将占用的约数；
	 *  没有要下载的东西时为 `None`（应用本身随客户端发布，不另占空间）。
	 */
	size_bytes: number | null,
	/**  它拥有的活动栏空间（启用后出现在活动栏上）。 */
	space: WorkspaceSpaceDto | null,
	/**  它拥有的 `luna.type`：这些笔记的专属入口随启用状态出现与收回。 */
	note_types: string[],
	/**  声明的权限（展示顺序）。 */
	permissions: AppPermissionDto[],
	/**  贡献的入口种类（展示顺序）。 */
	contributions: AppContributionDto[],
	/**  需要下载的第三方组件（展示顺序；没有就是空）。 */
	components: AppComponentDto[],
	/**  详情页的亮点 id（文案键 `apps.<id>.highlight.<亮点>.title|body`）。 */
	highlights: string[],
};

/**  应用基本信息（命令响应）。`capabilities` 来自 `luna-core::Capability::ALL`。 */
export type AppInfo = {
	/**  产品名。 */
	name: string,
	/**  版本。 */
	version: string,
	/**  产出这一份可执行文件的 Git 提交 SHA（由 `build.rs` 注入，禁止由前端猜测）。 */
	git_sha: string,
	/**  云端 wire 协议版本（`luna_cloud::protocol::CLIENT_PROTOCOL` 是唯一事实源）。 */
	protocol_version: number,
	/**  构建时刻（UTC RFC 3339；可复现构建由 `SOURCE_DATE_EPOCH` 固定）。 */
	build_time: string,
	/**  本构建声明的能力名（snake_case，来自 luna-core，单一来源）。 */
	capabilities: string[],
};

/**  一次安装的结果。 */
export type AppInstallOutcomeDto = {
	/**  装上了、但因推荐组件没装成而受限：那几件组件的 id（界面如实说哪一项受限）。 */
	limited_by: string[],
};

/**  「安装」确认框要说的事（ADR-168 ③）：它可以做什么、要下载什么、本机已有什么。不联网。 */
export type AppInstallPlanDto = {
	id: string,
	permissions: AppPermissionDto[],
	/**  要下载的组件（按清单顺序；没有就是空，确认框只列权限）。 */
	downloads: AppDownloadDto[],
	/**  本机已有、将直接使用的组件 id（用户自己装的那几件）。 */
	present: string[],
	/**  要下载但严格本地模式开着：确认框不给「安装」，给「去关闭严格本地」。 */
	strict_local_blocked: boolean,
};

/**  用户看到的应用状态（ADR-168 ①，`luna_config::apps::lifecycle` 的投影）。 */
export type AppLifecycleDto = "not_installed" | "installed" | "paused" | "needs_repair" | "update_available";

/**  一方应用的权限（详情页「权限与数据」）。 */
export type AppPermissionDto = "vault_folder" | "microphone" | "network" | "ai" | "external_programs";

/**  启动就绪事件（低频 typed event）。 */
export type AppReady = {
	/**  版本。 */
	version: string,
};

/**  一个可装的新版本（发给界面）。发布说明是发布者写的纯文本，界面按文本显示。 */
export type AppReleaseDto = {
	version: string,
	current_version: string,
	notes: string | null,
	/**  发布日期（RFC 3339）；清单没写就是 `None`。 */
	date: string | null,
};

/**  音频输入设备 DTO（HUD 设备选择）。 */
export type AudioInputDeviceDto = {
	/**  设备名（即 `recording.input_device` 设置值）。 */
	name: string,
	/**  是否系统默认输入。 */
	is_default: boolean,
};

/**
 *  同步回放聚合包（`load_sync_playback` 返回值）。
 *  一条书签（PRD-04-005）：毫秒来自 frontmatter 精确层，备注来自正文 🔖 行。
 */
export type BookmarkDto = {
	ms: number | null,
	note: string | null,
};

/**  脚本里的一个 B-roll 镜头（PRD-19-026）：`broll` 代码块。 */
export type BrollShotDto = {
	/**  所在段的段名；开场为 `None`。 */
	section: string | null,
	/**  开头围栏所在行（含 frontmatter，1 起，与段的 `line` 同一口径）。 */
	line: number,
	text: string,
	/**  已拍 / 已找到（围栏信息串里的 `done`）。 */
	done: boolean,
};

/**  一条待保存的字幕（原文 + 可选译文），由前端按句配对后传入。 */
export type CaptionLineDto = {
	/**  原文（可能为空——仅译文行）。 */
	source: string,
	/**  译文（无则 `None`）。 */
	translation: string | null,
};

/**
 *  某扇字幕窗被收起（PRD-04-040 / 044）。字幕窗常驻，收起只是 hide，网页里的状态原样
 *  留着——收起时开着的「外观与显示」面板，下一次打开还开着，看上去像「打开字幕默认就弹出
 *  设置」（真机 2026-10-02，只在上次关时面板开着才出现，所以「不是每次」）。译文窗还会被
 *  原文窗收起（选回同窗双语、会话结束），它自己无从得知，只能由 Rust 在收起处说一声。
 *  全局广播、载荷带 label，两扇窗各认自己的。
 */
export type CaptionWindowHidden = {
	/**  被收起的窗口 label（`live-caption` / `live-caption-translation`）。 */
	label: string,
};

/**
 *  一段文本要落进**哪个目的地**（PRD-06-058 P0-1 收口）。
 *
 *  **这是前端唯一有资格回答的问题，也是它在这条路上唯一交出去的东西**：「用户此刻
 *  站在哪个目的地里」是导航状态，前端本来就持有；而「记录该存成什么类型、落哪个目录、
 *  按哪套惯例命名」是**判定**，只在 [`notes::destination_note_plan`] 一处（ADR-003）。
 *
 *  反过来做（前端按目的地挑两个不同命令、或直接传类型字面量）等于把业务判定搬进界面层：
 *  侧栏捕获框与空白画布从此可以各自漂，而它们漂开的表现正是本条要修的那件事——用户站在
 *  「记录」里，最显眼的输入区却创建了知识笔记。
 */
export type CaptureDestinationDto =
/**  「笔记库」目的地：动笔写 → 知识笔记（`type: note`，落 `vault.notes_dir`）。 */
"notes" |
/**  「记录」目的地：随手记 → 记录（与侧栏捕获框**同一条**落盘路径）。 */
"drafts";

/**  渠道目录里的一个渠道（内置或自定义）。 */
export type ChannelDto = {
	id: string,
	/**  自定义渠道的名字；内置为 `None`（界面按 id 取译名）。 */
	name: string | null,
	format: ChannelFormatDto,
	limits: ChannelLimitsDto,
	/**  自定义渠道的风格说明；内置为 `None`。 */
	style: string | null,
	builtin: boolean,
	/**  发布须知：这个平台要求发布时声明 AI 内容（界面按 id 取 `creator.channelNotice.<id>`）。 */
	ai_notice: boolean,
};

/**  「我的渠道」里的一项（ADR-166 ⑦）：选择渠道时只列这些；`default` = 新项目默认发。 */
export type ChannelFavoriteDto = {
	id: string,
	default: boolean,
};

/**  渠道的形态（ADR-166）。 */
export type ChannelFormatDto = "long_video" | "short_video" | "article" | "post" | "newsletter" | "audio";

/**  渠道的约束；`None` = 没有上限或还没核对。 */
export type ChannelLimitsDto = {
	title_max: number | null,
	body_max: number | null,
	tags_max: number | null,
	tag_max: number | null,
	clip_max_secs: number | null,
};

/**  一处不合规（章号、行号都从 1 起，界面直接显示）。 */
export type ChapterIssueDto = { kind: "unparsed"; line: number } | { kind: "first_not_at_zero" } | { kind: "too_few"; count: number } | { kind: "too_short"; chapter: number; seconds: number } | { kind: "not_increasing"; chapter: number } | { kind: "empty_title"; chapter: number } | { kind: "past_end"; chapter: number };

/**  一段章节文字的检查结果：哪里不合规；能自动修时给出修好的文字。 */
export type ChaptersCheckDto = {
	issues: ChapterIssueDto[],
	/**  按规则修正后的文字；已经合规、或修了也不会变时为 `None`。 */
	fixed: string | null,
};

/**  AI 给出的章节草稿：可直接改的文字 + 它的检查结果 + 成片时长（之后边改边检查要用）。 */
export type ChaptersDraftDto = {
	text: string,
	check: ChaptersCheckDto,
	/**  成片时长（毫秒）；不知道为 `None`。 */
	duration_ms: number | null,
};

/**  Chat 流式命令事件。仅下行（Rust → 前端），故不派生 `Deserialize`。 */
export type ChatEvent =
/**  已开始。 */
{ kind: "started" } |
/**  上下文超预算被截断（PRD-03 §5 显式提示，不静默）。 */
{ kind: "truncated"; data: {
	/**  实际提交 token 数。 */
	tokens_in: number,
	/**  输入预算上限。 */
	input_limit: number,
} } |
/**
 *  本轮的库内检索结果（PRD-16-006）。**在流式开始前**下发，故引用角标不依赖
 *  生成结束即可点击；`sources` 为空即「未找到相关内容」的诚实降级信号。
 */
{ kind: "retrieval"; data: RetrievalInfoDto } |
/**  流式 token 增量（PRD-03-002 [P0] 流式输出）。 */
{ kind: "token"; data: string } |
/**  完成（最终 assistant 全文 + 被实际引用的出处）。 */
{ kind: "done"; data: {
	/**  最终回答全文。 */
	text: string,
	/**  回答里 `[n]` 真正引用到的出处（解析在 Rust，前端只渲染）。 */
	sources: RetrievalSourceDto[],
	answer_meta: AnswerMetaDto | null,
} } |
/**  失败（结构化，PRD-03 §5）。 */
{ kind: "failed"; data: ChatFailureDto } |
/**  已取消（保留已产 token，PRD-03-007）。 */
{ kind: "cancelled"; data: string };

/**  结构化失败载荷（PRD-03 §5：结构化错误 + 修复建议；前端按 `code` 映射 i18n 文案与动作）。 */
export type ChatFailureDto = {
	/**  稳定错误码（SCREAMING_SNAKE，`luna_core::JobError::code`）。 */
	code: JobErrorCodeDto,
	/**  是否可原样重试（TDD-01 §5.6）。 */
	retriable: boolean,
	/**  服务端要求的最短等待秒数。只对 `RATE_LIMITED` 有值；`None` = 对方未给提示。 */
	retry_after_secs: number | null,
};

/**
 *  历史会话的一页（PRD-03-013）。
 *
 *  游标挂在**信封**上而不是逐行：这条命令的返回本来就要带一个权威总数，套信封没有额外
 *  代价（与 `DraftInboxDto` 同一形态；裸数组那几个消费者才把游标挂末行）。
 */
export type ChatHistoryDto = {
	/**
	 *  全库会话总数（侧栏计数徽标用）。
	 *
	 *  **不受列表上限截断**：徽标承诺的是「一共有几场」，拿已加载条数去充数，
	 *  在满页时就是谎报一个上限值。
	 */
	total: number,
	/**  **这一页**的条目（修改时间倒序）。 */
	entries: ChatHistoryEntryDto[],
	/**  下一页的键集游标；`null` = 已遍历到底（TDD-07 §4.1a）。游标不透明，前端只回传。 */
	next_cursor: string | null,
	/**
	 *  会话能不能**生成知识笔记**（PRD-06-044）。
	 *
	 *  挂在信封上而不是逐行：这一项的资格由**类型**决定——`NoteType::Chat` 恒为资料
	 *  （`NoteStage::resolve` 在 `is_source_material()` 上直接返回，frontmatter 改不动它），
	 *  于是逐行下发就是一列恒为 true 的布尔，把常量伪装成数据。前端仍然不自己拼判据。
	 */
	distillable: boolean,
	/**
	 *  会话能不能作为「多条 → 一篇」的源（PRD-06-047）。
	 *
	 *  同上是类型级：`merge_block` 只挡聚合页，而主题页 / 知识地图都是 `type: note`。
	 *  有人手工往一篇会话里写 `luna.topic: true` 时菜单会多给一项，那一次由命令层如实
	 *  拒绝并回流原因——「前端不渲染只是不渲染，命令仍独立判定」是本仓既有口径。
	 */
	mergeable: boolean,
	/**
	 *  一次汇总最少 / 最多几条（PRD-06-047）——与 `DraftInboxDto` 的那两个是**同一对
	 *  常量**。
	 *
	 *  **常量归 Rust**：前端照着写一个 `> 1` 在这里，就是同一条规则的第二处定义，
	 *  改了一边不会有任何东西变红，而表现只是"菜单说可以、点下去被拒"。
	 */
	merge_min: number,
	merge_max: number,
};

/**  历史会话列表条目（PRD-03-013：Vault `type: chat` 笔记即会话，笔记即文件铁律）。 */
export type ChatHistoryEntryDto = {
	/**  笔记相对路径（载入/删除/跳转笔记库的键）。 */
	path: string,
	/**  标题（= 文件名 stem，归档命名含时间与首问摘要）。 */
	title: string,
	/**  修改时间（Unix 毫秒；索引缺省 0）。 */
	modified_ms: number | null,
};

/**  一条对话消息投影（`System` 角色不外发——系统提示词属预设实现细节）。 */
export type ChatMessageDto = {
	/**  角色（`user` / `assistant`）。 */
	role: string,
	/**  文本内容。 */
	content: string,
	/**
	 *  本条回答实际引用的出处（PRD-16-005）。只含**被引用**的那几条——
	 *  把检索到的全摆出来会让用户以为每条都被采信了。
	 */
	sources: RetrievalSourceDto[],
	/**  本轮开启知识检索后才有；普通对话保持 `None`，不得被误读为 ModelOnly。 */
	answer_meta: AnswerMetaDto | null,
};

/**
 *  选区带入就绪广播（PRD-03-008）：**不携带正文**（正文经 `chat_prefill_take` 单次拉取，
 *  不进事件系统，TDD-12 日志/事件脱敏纪律）。
 */
export type ChatPrefillReady = {
	/**  目标作用域（当前恒为 `panel`）。 */
	scope: ChatScope,
};

/**  对话角色预设投影（PRD-03-010）。`name` 为回退展示名，前端优先按 id 走 i18n。 */
export type ChatPresetDto = {
	/**  预设 id（如 `chat_general`）。 */
	id: string,
	/**  回退展示名。 */
	name: string,
};

export type ChatRouteKind = "managed_service" | "on_device";

/**  对话表面（会话作用域）。每个作用域一个独立内存会话（PRD-03-012）。 */
export type ChatScope =
/**  主窗口「对话」标签页。 */
"workspace" |
/**  全局快捷键唤起的非激活面板（`quick-chat` 窗口）。 */
"panel";

/**  会话快照：视图挂载时经 `chat_attach` 恢复（PRD-03-012 App 运行期连续性）。 */
export type ChatSnapshotDto = {
	/**  作用域。 */
	scope: ChatScope,
	/**  已落账消息（不含进行中一轮的流式部分）。 */
	messages: ChatMessageDto[],
	/**  是否有进行中的生成（重挂载时提示"正在生成"，终局经 `chat://changed` 通知刷新）。 */
	busy: boolean,
	/**  **临时对话**（PRD-03-012）：本会话不落盘/不进历史/退出即弃。`true` = 临时。 */
	temporary: boolean,
	/**  当前角色预设 id（`None` = 无系统提示词）。 */
	preset_id: string | null,
	/**  已链接的归档笔记相对路径（PRD-03-013：历史会话列表高亮当前会话的依据）。 */
	note_path: string | null,
	/**  本会话是否检索知识库（PRD-16-005 输入区芯片的真值）。 */
	grounding: boolean,
};

/**
 *  一轮生成终局广播（低频 typed event）：重挂载/其它视图收到后重新 `chat_attach`；
 *  本视图据 `note_path` 同步归档链接（持久会话本轮自动归档可能建立/更新链接，PRD-03-013）。
 */
export type ChatTurnEnded = {
	/**  终局的作用域。 */
	scope: ChatScope,
	/**  终局后的归档笔记链接（临时会话恒 `None`）。 */
	note_path: string | null,
};

/**  一张建议卡（`PRD-16-032`）。仅下行。 */
export type CheckupFindingDto = {
	/**  稳定 id（忽略按它对齐）。 */
	id: string,
	/**  种类 kebab 键——**前端按它查 i18n 取文案**，Rust 不出人读文案。 */
	kind: string,
	/**  涉及页（芯片）。第一项 = 「打开」的落点。 */
	paths: string[],
	/**  「打开」要落到的行（1-based）；`None` = 只打开笔记。 */
	line: number | null,
	/**  被指认的原文（那条声明 / 断链的链接目标）。 */
	subject: string,
	/**  判定理由（模型产出，仅深度体检有）。 */
	reason: string,
	/**  覆盖的对象数（积压 N 篇 / 断链被 N 页引用）。`0` = 不适用。 */
	count: number,
	/**  这条能不能被 ✕（积压卡不能——它会自己消失，判定在 Rust）。 */
	ignorable: boolean,
	/**
	 *  这条是不是**流水线积压**：知识库脉搏已把它放在主位，故启动概览的体检一行
	 *  **不数它**（否则同一件事在同一屏说两遍）。判定在 Rust，前端只按结果过滤。
	 */
	backlog: boolean,
	/**  「修复经预览」走哪条既有流程；`None` = 这一类没有确定性修复，只给「打开」。 */
	fix: string | null,
};

/**  深度体检预检：确认卡据此在**点开始之前**陈述代价（`PRD-16-031` 六要素之二）。 */
export type CheckupPreflightDto = {
	/**  待核对的声明条数（= 本次要跑多少次本地模型）。 */
	claims: number,
	/**  覆盖的主题页数。 */
	topics: number,
	/**  近重复检测是否可用（语义索引在场）。`false` = 这一项**诚实跳过**，不静默给空结果。 */
	semantic_ready: boolean,
	/**  是否已有一次在跑。 */
	running: boolean,
};

/**  深度体检进度（`checkup://progress`）。逐条低频（每条一次 LLM），无需节流。 */
export type CheckupProgress = {
	/**  已核对的声明数（含失败）。 */
	done: number,
	/**  本次总条数。 */
	total: number,
	/**  已发现的问题数。 */
	found: number,
	/**  判定失败的条数。 */
	failed: number,
	/**  终态标记。 */
	finished: boolean,
	/**  用户主动取消。 */
	cancelled: boolean,
	/**  连续失败提前中止（引擎不可用的典型指纹）。 */
	halted: boolean,
};

/**  一次体检报告（T0 + 最近一次深度体检的留存）。仅下行。 */
export type CheckupReportDto = {
	findings: CheckupFindingDto[],
	/**  因每类上限被折起来的条数（如实报数，不静默截断）。 */
	truncated: number,
	/**
	 *  上一次深度体检的完成时刻（毫秒）；`None` = 从未跑过。
	 *  `f64`：`i64` 跨 IPC 会被 specta 判为 BigInt 风格类型而拒绝（与 `NoteRefDto`
	 *  的 `modified_ms` 同一处置；毫秒时间戳在 f64 的 53 位尾数内无精度问题）。
	 */
	deep_ran_at_ms: number | null,
	/**  是否有一次深度体检正在跑。 */
	deep_running: boolean,
};

/**  复合锚（ADR-026 ⑥）的前端投影。前端只搬运、不解析——解析恒在 Rust。 */
export type CitationAnchorDto = {
	/**  标题路径（`["项目 X", "本周进展"]`）。 */
	heading_path: string[],
	/**  引文。 */
	quote: string,
	/**  引文前的上下文（消歧用）。 */
	prefix: string,
	/**  引文后的上下文（消歧用）。 */
	suffix: string,
	/**  行提示（1-based，相对整篇文件）。 */
	line_hint: number,
	/**  生成锚点时的源正文指纹；用于归档后识别来源发生过变化。 */
	source_hash: string,
};

/**
 *  引用打开的封闭终态。Rust 同时拥有源文件检查、锚解析与工作区导航，前端不能再把
 *  “解析成功”误当成“实际打开成功”。
 */
export type CitationOpenOutcome = "exact" | "moved" | "heading_only" | "lost" | "source_missing";

/**  引用跳转的解析结果（PRD-16-012）。仅下行。 */
export type CitationTargetDto = {
	/**  目标行（1-based，相对整篇文件）；`None` = 完全锚不上，只打开笔记。 */
	line: number | null,
	/**
	 *  是否精确命中引文。`false` **必须**向用户如实说明「原文已改动」——
	 *  静默跳到大概位置比说不知道更糟（ADR-026 ⑥ 反过度信任纪律）。
	 */
	exact: boolean,
};

export type ClipboardContentDto = {
	text: string | null,
	html: string | null,
};

/**  「云端库」里的一行。时刻是 Unix 毫秒（`f64` 因 specta 不收 64 位整数）。 */
export type CloudVaultDto = {
	id: string,
	/**  解开的库名；解不开、也没解开过 = `None`（界面写「名字暂不可读」）。 */
	name: string | null,
	/**  删除前要照着输入的字：库名；名字读不出时是库 id 的前 8 位。 */
	confirm_text: string,
	/**  云端占用的密文字节（含历史版本）。已删除的库是恢复后会加回容量的量。 */
	cloud_bytes: number | null,
	/**  最近一次提交的时刻；还没有提交 = 建库时刻。 */
	last_changed_ms: number | null,
	place: CloudVaultPlaceDto,
	/**  可以「下载到本机」：没删、也不在这台设备上。 */
	can_download: boolean,
	/**  可以「删除云端库」：还没删。成员能不能删组织的库由服务端判（403）。 */
	can_delete: boolean,
	/**  可以「恢复」：已删除且还在恢复期内。 */
	can_restore: boolean,
};

/**  一个云端库在这台设备上的处境。 */
export type CloudVaultPlaceDto =
/**  这台设备正把它同步到这个本地库。 */
{ kind: "here"; vault_path: string; local_name: string; display_path: string } |
/**  不在这台设备上。 */
{ kind: "not_here" } |
/**  已删除（所有设备都停止同步了）；`purge_after_ms` 之前可恢复，之后彻底清除。 */
{ kind: "deleted"; deleted_ms: number | null; purge_after_ms: number | null };

/**  组件对应用有多要紧（详情页「组件」一节的标签，ADR-167 ⑤）。 */
export type ComponentNeedDto = "required" | "recommended" | "optional";

/**  一件组件在这台机器上的情况（ADR-168 ①）。 */
export type ComponentPresenceDto = "missing" |
/**  Lunarca 下载的那一份。 */
"managed" |
/**  用户自己装的（Homebrew 等），Lunarca 不动它。 */
"external";

/**  一件组件的更新检查结果。 */
export type ComponentUpdateDto = {
	latest_version: string,
	update_available: boolean,
};

/**
 *  **AI 算力此刻落在哪**——界面的单一事实源。
 *
 *  # 与 [`CloudAvailability`] 的分工
 *
 *  那个回答「**能不能**走云」（门控，用于拦截）；这个回答「**在哪跑**」（状态，用于
 *  展示）。两者共用同一套判据、后者由前者派生——各算一遍必然有一天两处说不一样的话
 *  （门控放行而界面说「在本机跑」，或者反过来）。
 *
 *  # 为什么要有这个类型
 *
 *  此前「算力在哪」这件事没有名字：它散在四个设置项里，谁想知道就自己组合一遍
 *  （`strict_local` + 登录态 + `api_base` 是否为空 + 转写开关）。于是每个界面各判一次、
 *  各判各的，而用户看到的却是同一件事的不同说法。
 */
export type ComputeLocation =
/**  严格本地：全部在这台设备上跑，任何外发都被硬拦（用户显式选的隐私档）。 */
"strict_local" |
/**
 *  本机：没登录、也没连组织服务端。算力在设备上，但用户随时可以连。
 *
 *  这是 ADR-037 的默认态——**不产生任何云网络行为**。
 */
"on_device" |
/**  官方云（内置地址，用户不必填）。 */
"official_cloud" |
/**  组织服务端（私有化部署，地址由部署方给）。 */
"organization";

/**
 *  一条能力此刻的**有效执行位置 + 为什么是它 + 从哪儿改**（ADR-059 ④）。
 *
 *  # 为什么「为什么」必须一起下发
 *
 *  算力卡此前只说「服务端 / 这台设备」。同样是「这台设备」，背后可能是四件完全不同的事：
 *  用户自己选的、隐私档压的、还没同意把麦克风交出去、或者服务端根本不提供这条能力。
 *  它们的下一步动作互不相同，而卡片给的是同一个词——于是用户只能逐个槽位去翻设置，
 *  才能发现「原来是我某次自己钉的」。同行做法（Cursor / Copilot / Raycast）一律把有效
 *  位置与理由摆在一起，并就地给切换入口。
 *
 *  判定全在 Rust（ADR-003）：前端拿 `reason` 取一句文案、拿 `setting_key` 拼深链，不自己推。
 */
export type ComputeRouteDto = {
	/**  `chat` / `embedding` / `transcription`。前端按它取标题，不解析槽位名。 */
	capability: string,
	/**  此刻**实际**在哪跑。 */
	location: ModelExecutionLocation,
	/**  为什么是这个位置。 */
	reason: ComputeRouteReason,
	/**  决定这条能力的槽位设置键——就地切换入口（`settings://ai_services/<key>`）。 */
	setting_key: string,
	/**  这条能力此刻**可以**交给服务端吗。`false` 时不摆一个点了也没用的入口。 */
	can_use_server: boolean,
};

/**  「为什么是这个执行位置」。 */
export type ComputeRouteReason =
/**  「仅本地」隐私档硬拦：任何服务端选择此刻都不生效（ADR-038 ④）。 */
"strict_local" |
/**  用户在这条能力上**显式**选了本机模型。连接状态不改写它（ADR-037/048）。 */
"explicit_device" |
/**  用户**显式**把这条能力交给了服务端。 */
"explicit_server" |
/**  没人选过，服务端在，按「连上即用」落到服务端（ADR-037）。 */
"server_default" |
/**  没人选过，也没有可用服务端，落到设备策略档（ADR-059 起按已装清单挑）。 */
"device_policy" |
/**  差一次单独同意才会上服务端（麦克风与会议录音，ADR-038 ④）。 */
"needs_consent" |
/**  服务端不提供这条能力（或此刻用不了），退到本机。 */
"server_unavailable" |
/**  已登录，但这台服务端没给这项能力配上游（ADR-041 ①），在本机跑。 */
"server_not_configured" |
/**  已登录，但账户所在组织没开放这项能力（配额策略的能力开关，统一登录 R4b），在本机跑。 */
"server_not_allowed" |
/**  「优先在哪运行」设成了本机优先：服务端在，但这条能力先在本机跑。 */
"strategy_local" |
/**  「优先在哪运行」设成了仅本机：外部候选一律不进路由，连着服务端也不外发。 */
"strategy_local_only" |
/**  设成了本机优先，但本机解析不出可用模型，这条能力暂由服务端执行。 */
"strategy_local_unavailable";

export type ComputeServiceDto = {
	id: string,
	name: string,
	/**  `ready` / `unavailable`。 */
	status: string,
	managed_by: string,
	/**  网络服务的实际端点；进程内运行时为空。 */
	endpoint: string | null,
	model_count: number,
	latency_ms: number | null,
};

/**
 *  「AI 在哪跑」的一次性快照——设置首屏与首启引导**共用同一份事实**。
 *
 *  由 Rust 一次算清，而不是前端拿四个设置项自己拼（ADR-003 前端零业务）。
 *  此前「算力在哪」没有名字，谁想知道就各组合一遍 `strict_local` + 登录态 +
 *  `api_base` + 转写开关——于是同一件事在不同界面上说法不同，而没有任何东西会变红。
 */
export type ComputeStatusDto = {
	/**  算力此刻落在哪。 */
	location: ComputeLocation,
	/**
	 *  三条能力此刻的**有效执行位置 + 为什么是它 + 从哪儿改**（ADR-059 ④）。
	 *
	 *  取代此前的三个布尔（`chat_on_server` / `embedding_on_server` /
	 *  `transcription_on_server`）。布尔只说得出「在不在服务端」，而同一个「在这台设备」
	 *  背后有四种互不相同的原因与四种不同的下一步动作；用户于是只能逐个槽位去翻设置，
	 *  才能发现是自己某次钉的。同一事实不留两种表示（ADR-046）。
	 */
	routes: ComputeRouteDto[],
	/**
	 *  服务端路径可用时的本机候选。`chat` / `transcription` 可在严格边界内兜底，
	 *  `embedding` 明确为 `explicit_only`，避免把云端嵌入透明改写为本地索引结果。
	 */
	local_candidates: LocalCandidateDto[],
	/**
	 *  仍显式钉在本机、而服务端此刻跑得了的能力（一次性交接提示的对象）。
	 *
	 *  空 = 不提示：要么没有这种槽位，要么这台服务端已经问过一次（`compute.handover_prompted_for`）。
	 */
	pending_handover: string[],
	/**
	 *  `managed_service` / `on_device`。
	 *  前端据此选择展示文案，不得再从本机模型目录推断当前执行路径。
	 */
	chat_route_kind: ChatRouteKind,
	/**
	 *  服务端转写此刻为什么用不了；`None` = 能用，同意项可以勾。
	 *
	 *  结论连同原因一起下发：界面按原因换说明，不拿 `signed_in` + `location` 自己拼（ADR-003）。
	 */
	transcription_server_blocker: TranscriptionServerBlocker | null,
	/**  「优先在哪运行」设成了仅本机：连着服务端也不外发。卡头据此换说法。 */
	outbound_blocked_by_strategy: boolean,
	/**
	 *  连着的服务端一个上游都没登记（ADR-041 ①）：卡头如实说「尚未配置算力，在本机运行」，
	 *  而不是「请求发往服务端」。
	 */
	server_setup_incomplete: boolean,
};

/**  一份冲突副本。 */
export type ConflictCopyDto = {
	path: string,
	kind: ConflictKindDto,
	/**  它是哪一篇的副本；git 冲突标记在原文自己身上，为 `None`。 */
	original: string | null,
};

/**  冲突副本从哪来。 */
export type ConflictKindDto = "syncthing" | "dropbox" | "icloud" | "git_markers";

/**  「检查更新」问的是哪一份目录。 */
export type ContentCatalogDto = "themes" | "templates";

/**
 *  CoreML 编码器的安装阶段（`model://coreml-phase`，ADR-115 / PRD-14-020「转换带进度」）。
 *
 *  字节进度仍走 `model://download-progress`（`model_id` = `<id>#coreml`）；本事件只讲
 *  阶段：`downloading` → `extracting` → `compiling`（子进程探针里的首次 ANE 编译，可达
 *  数分钟）→ `ready`；探针没过则 `failed`（编码器被挪到 `.disabled`，转写照常走 Metal/CPU）；
 *  用户移除即 `removed`。
 */
export type CoremlPhase = {
	model_id: string,
	phase: CoremlPhaseKind,
	/**  阶段起点（Unix 毫秒）：前端据此显示「已编译 N 秒」。 */
	started_at_ms: number | null,
};

export type CoremlPhaseKind = "downloading" | "extracting" | "compiling" | "ready" | "failed" | "removed";

/**  一条动作状态。 */
export type CreateActionEntryDto = {
	/**  动作 id。 */
	id: CreateActionIdDto,
	/**  此刻的状态。 */
	state: CreateActionStateDto,
};

/**  五类创建动作的稳定 id（与 `luna_config::CREATE_ACTIONS` 穷尽映射）。 */
export type CreateActionIdDto =
/**  文字速记 → 「速记」。 */
"text_quick_note" |
/**  语音速记 → 「速记」。 */
"voice_quick_note" |
/**  新建笔记 → 「笔记」。 */
"new_note" |
/**  开始录音 → 「录音」。 */
"start_recording" |
/**  导入资料：音视频 → 「转写」，文档 → 文档文件夹（ADR-164 ⑩）。 */
"import_material";

/**
 *  暂时执行不了的**封闭原因**（TDD-07 §2.2）。
 *
 *  **封闭而不是自由文本**：前端要按原因决定说哪句话、给哪个修复入口，而自由文本只能
 *  被原样渲染——那等于把本地化和交互决策一起丢给了一个字符串。
 */
export type CreateActionReasonDto =
/**  还没有打开的笔记库（含切库过渡期）。 */
"vault_unavailable" |
/**  麦克风权限尚未询问过——点一下就能申请。 */
"microphone_permission_required" |
/**  麦克风权限已被拒绝/撤销——只能去系统设置里改。 */
"microphone_permission_denied" |
/**  麦克风被另一路采集占着（实时字幕 / 语音输入 / 弹窗语音，硬互斥）。 */
"audio_busy" |
/**  已有一个语音输入会话在进行中。 */
"voice_session_busy" |
/**
 *  已有一场**录音**在进行中（B2）：入口不是禁用，而是「回到录音」。
 *
 *  此前它被并进 `audio_busy`——「麦克风正被另一处采集占用」。可那"另一处"就是
 *  用户自己刚关掉面板的那场录音：麦克风在录、文件在长，而界面上既看不出来、也回不去，
 *  只剩热键把它停掉。
 */
"recording_in_progress" |
/**  没有可用的转写能力（既没有本地权重，也没有服务端通道）。 */
"asr_unavailable" |
/**  转写要走服务端，而用户还没同意把麦克风内容上云。 */
"service_consent_required" |
/**  本平台没有采集类入口依赖的 HUD 窗口（见 `CAPTURE_PLATFORM_SUPPORTED`）。 */
"unsupported_platform";

/**  修复动作（TDD-07 §2.2）。 */
export type CreateActionRepairDto =
/**  打开设置的某个目标。 */
{ kind: "open_settings";
/**  目标深链。 */
route: CreateActionSettingsRouteDto } |
/**  申请麦克风权限（复用既有 `request_permission`）。 */
{ kind: "request_microphone_permission" } |
/**  把已在进行的语音会话 HUD 显示出来（复用 `voice_input_show_hud` 的保留会话行为）。 */
{ kind: "show_voice_session" } |
/**  回到进行中的录音（`recording_show_hud`：只显示常驻面板，不碰会话）。 */
{ kind: "show_recording_session" };

/**
 *  修复用的设置深链——**wire 值直接就是深链本身**（TDD-07 §2.2）。
 *
 *  前端**原样**交给 `open_workspace_route`，不拼 URL：拼接意味着前端要知道页名与
 *  键名，而那是 Rust 注册表的事；拼错了只会在点下去的那一刻变成一次静默的 no-op。
 */
export type CreateActionSettingsRouteDto =
/**  笔记库路径那一行。 */
"settings://notes/storage.vault_root" |
/**  存储与隐私页。 */
"settings://notes" |
/**  AI 算力与模型页。 */
"settings://ai_services";

/**  一次完整快照：**每个已支持 id 恰好一条**。 */
export type CreateActionSnapshotDto = {
	/**
	 *  进程内单调递增的版本号——前端只接受不旧于当前的快照。
	 *
	 *  没有它就没法处理竞态：订阅与查询是两条路，慢的那次查询回来时可能已经过时，
	 *  而"过时的可用性"会让一个刚被授权的动作重新变灰。
	 */
	revision: number,
	/**  五条状态（顺序即「添加内容」的呈现顺序）。 */
	actions: CreateActionEntryDto[],
};

/**
 *  一个动作此刻的状态。
 *
 *  **判别联合，不是"三态枚举 + 两个可空字段"**：后者能拼出 `available` 却带着一个
 *  reason、或者 `needs_attention` 却没有 repair 这类非法组合，而每个消费者都要各自防一遍。
 */
export type CreateActionStateDto =
/**  现在就能用。 */
{ kind: "available" } |
/**  暂时不能用，且**没有**可一键执行的修复（只能说明原因）。 */
{ kind: "unavailable";
/**  原因。 */
reason: CreateActionReasonDto } |
/**  暂时不能用，但有明确的下一步。 */
{ kind: "needs_attention";
/**  原因。 */
reason: CreateActionReasonDto;
/**  修复动作。 */
repair: CreateActionRepairDto };

/**  快照变化事件（`create-actions://states-changed`，携同形快照）。 */
export type CreateActionStatesChanged = CreateActionSnapshotDto;

/**
 *  看板数据：显示的列（按用户的列序）、隐藏的列、全部卡片。列序由 Rust 给出，前端不自带
 *  一份阶段清单。
 */
export type CreatorBoardDto = {
	/**  当前视图（设置 `creator.board_view`）。 */
	view: CreatorBoardViewDto,
	stages: ProjectStageDto[],
	/**  用户收起的列（按列序）——「看板列」菜单里未勾选的那几项。 */
	hidden_stages: ProjectStageDto[],
	/**  看板、列表、表格、日历与侧栏项目清单里的项目（不含已归档）。 */
	projects: ProjectCardDto[],
	/**  已归档的项目（侧栏「已归档」一节；ADR-165 S6）。 */
	archived: ProjectCardDto[],
};

/**  看板的视图：同一份项目数据的三种看法（PRD-19-003）。 */
export type CreatorBoardViewDto =
/**  按阶段分列，拖动卡片改阶段。 */
"board" |
/**  按阶段分组的紧凑清单，组可折叠。 */
"list" |
/**  一行一个项目，就地改阶段。 */
"table" |
/**  按计划发布日期排的月历，拖到某一天即改日期（PRD-19-040）。 */
"calendar";

/**  转写 Cue 点（前端时间轴跳转，TDD-06 §2.1）。 */
export type CuePointDto = {
	/**  绝对起点（ms）。TS `number`（f64）。 */
	start_ms: number | null,
	/**  绝对止点（ms）。TS `number`（f64）。 */
	end_ms: number | null,
	/**  转写文本（已落盘，供只读展示；前端不向后端回传）。 */
	text: string,
	/**  译文（实时转译/二次转译产物；`None` = 该段无译文，PRD-04-025 双语回放）。 */
	translation: string | null,
	/**
	 *  说话人标签（PRD-04-053/054：`"self"`=我 / `"remote"`=对方 / `"remote:N"`=对方 N；
	 *  `None` = 单麦克风源无标签）。前端映射显示名（common:track.*）。
	 */
	speaker: string | null,
	/**
	 *  字幕规范问题（PRD-05-033）；空 = 合规。阈值与导出重切分同源（`CueConstraints`），
	 *  判定在 Rust——前端零业务只渲染徽标（ADR-003）。
	 */
	issues: SubtitleIssueDto[],
	/**  阅读速度（字符/秒）；`None` = 时长未知。供徽标显示"N 字/秒"，前端不自己算。 */
	cps: number | null,
};

/**  整篇转写编辑的一条 cue 文本改动（`update_playback_transcript` 入参）。 */
export type CueTextEditDto = {
	/**  段起点（会话绝对毫秒，匹配键）。 */
	start_ms: number | null,
	/**  段止点（会话绝对毫秒，匹配键）。 */
	end_ms: number | null,
	/**  新文本。 */
	text: string,
};

/**  新建或修改一个自定义渠道（`id` 为空 = 新建）。 */
export type CustomChannelInputDto = {
	id: string | null,
	name: string,
	format: ChannelFormatDto,
	limits: ChannelLimitsDto,
	style: string,
};

export type DataFootprintDto = {
	entries: FootprintEntryDto[],
};

/**  默认建议的 Vault 位置（PRD-14-040：给出默认建议而非空输入框）。 */
export type DefaultVaultPathDto = {
	path: string,
	/**  「文档」在 OneDrive 里，所以建议放到了用户目录下（首启与新建库据此说明原因）。 */
	avoided_onedrive: boolean,
};

/**  Vault delete mode DTO。 */
export type DeleteModeDto =
/**  系统回收站。 */
"trash" |
/**  Vault 内 `.trash/`。 */
"vault_trash" |
/**  永久删除。 */
"permanent";

/**  译境运行态变更。只投影“会话是否仍在运行”，不携带区域、截图或 OCR 内容。 */
export type DesktopLensChanged = {
	/**  `true` 表示镜头会话正在运行（即使用户刚点拍摄而镜框暂时隐藏）。 */
	active: boolean,
};

/**  一张便签此刻的内容与外观（便签窗挂载时取一次）。 */
export type DesktopNoteDto = {
	/**  这一篇的相对路径。 */
	path: string,
	/**  标题（= 文件名 stem）。 */
	title: string,
	/**  正文（已剥 frontmatter）。 */
	body: string,
	/**  配色键；`null` = 默认色。 */
	color: string | null,
};

/**  「已达到设备上限」那一步要渲染的全部事实（不含 `revoke_token`）。 */
export type DeviceLimitDto = {
	/**  这个账户最多几台设备。 */
	max: number,
	devices: LimitedDeviceDto[],
	/**  「移除一台并登录」在这之前有效（RFC 3339，界面只用来提示）。 */
	expires_at: string,
};

/**  设备档位（按内存划分，推导在 [`crate::hardware::derive_tier`]；PRD-14-010，TDD-04 §4）。 */
export type DeviceTier =
/**  低配（<8GiB）：只推荐小档，避免下载跑不动的大模型（PRD-14-011）。 */
"low" |
/**  标准（8–16GiB）：平衡档。 */
"standard" |
/**  高配（≥16GiB）：精度优先档。 */
"high";

/**  一行差异。 */
export type DiffLineDto = {
	/**  `equal` / `added` / `removed`。 */
	kind: string,
	old_line: number | null,
	new_line: number | null,
	text: string,
};

/**  因安全原因被服务端封禁、在本机停用的一套主题（PRD-18-012）：只能卸载；解除封禁后自动回到 `themes`。 */
export type DisabledThemeDto = {
	id: string,
	version: string,
	name: string,
	author: string,
	license: string,
	/**  服务端写的原因，原样给用户看。 */
	reason: string,
};

/**  批量里**被挡下的一篇**：是哪一篇、为什么。 */
export type DistillBatchRejectionDto = {
	/**  源笔记相对路径——界面据它渲染一行可点的条目。 */
	note_rel: string,
	/**
	 *  拒绝理由：稳定机器前缀 + 本地化说明（与单篇路径同一个串）。
	 *
	 *  **理由必须逐篇带出来**：这里此前是 `if enqueue_distill(..) == Ok(true)`，
	 *  `Err(理由)` 被整个丢进 `==` 的假分支里——50 篇里挡下 47 篇，用户拿回的是
	 *  一句「已加入 3 件」，另外 47 篇既没入队也没有任何交代。
	 */
	reason: string,
};

/**  批量入队的结果：进了几件、哪些没进、为什么。 */
export type DistillBatchStartDto = {
	/**  真入队篇数（幂等去重不计，「已加入 N 件」不虚报）。 */
	queued: number,
	/**  被挡下的篇目，顺序即扫描顺序。 */
	rejected: DistillBatchRejectionDto[],
};

/**
 *  生成选项（模板选单的数据源，PRD-06-051）。
 *
 *  **惰性获取**：只在用户展开选项浮层时调用一次。建议模板要读边车段落数说话人，而徽标的
 *  [`DistillStateDto`] 每次 `vault://changed` 都会刷新（且不带路径过滤）——把这份计算挂在
 *  那条路径上等于把一次文件 IO 焊死在高频面上。
 */
export type DistillOptionsDto = {
	/**
	 *  可选模板清单（顺序即呈现顺序）。
	 *
	 *  **由 Rust 下发而非前端硬编码**（ADR-003）：模板集与「哪个模板默认附整理稿」都是
	 *  业务事实，写死在前端就是第二份事实源——Rust 新增一个模板而前端没跟上时，那个模板
	 *  在浮层里根本不出现，且没有任何编译错误。
	 */
	templates: DistillTemplateChoiceDto[],
	/**  按规则建议的模板键（"自动适配"的实现）。 */
	suggested: string,
	/**  建议的判据（前端查 `distill.reason.*` 说明"为什么是它"）。 */
	reason: string,
	/**  此刻**实际会用**的模板键（已记录 > 建议）——浮层据此预选。 */
	template: string,
	/**  此刻实际会用的整理稿开关（已记录 > 模板默认值）。 */
	full_text: boolean,
};

/**  批量预检 DTO：确认卡据此在**点开始之前**陈述代价。 */
export type DistillPreflightDto = {
	/**  待整理篇数（从未生成 + 源已更新且未被编辑）。 */
	pending: number,
	/**  已最新、跳过的篇数。 */
	fresh: number,
	/**  蒸馏笔记已被编辑、跳过的篇数——**批量绝不覆盖用户资产**，这个数字要让用户看见。 */
	edited: number,
	/**  正文为空、无从整理的篇数。 */
	empty: number,
	/**  队列里是否已有蒸馏任务在排/在跑（确认卡据此提示"还有 N 件在队列里"）。 */
	running: boolean,
};

/**  预览结果：差异 + 落点。 */
export type DistillPreviewDto = {
	/**  蒸馏笔记路径（尚未写入的新笔记也给——用户要知道会落在哪儿）。 */
	target_path: string,
	/**  当前内容 → 重生成后内容的逐行差异（复用版本对比同一呈现，DRY）。 */
	diff: LineDiffDto,
};

/**  一篇笔记的蒸馏状态（前端徽标四态的唯一数据来源）。 */
export type DistillStateDto = {
	/**
	 *  该笔记是否**能**生成知识笔记（`NoteStage::allows_distill`：资料 ∪ 记录；
	 *  知识态笔记不渲染入口）。PRD-06-054 把这条入口从资料推广到用户记录。
	 */
	eligible: boolean,
	/**
	 *  它是不是**资料**（来源轴）——页头「资料」徽标据此渲染。
	 *
	 *  与 `eligible` 刻意分成两个事实：自 PRD-06-054 起「能生成知识笔记」不再等于
	 *  「是资料」，记录态同样能生成。共用一个布尔会让「资料」徽标盖到草稿头上——而它
	 *  说的三条待遇（不入图谱、不打标、搜索折叠成资料组）对记录**一条都不对**。
	 */
	source_material: boolean,
	/**  已生成的蒸馏笔记路径（`null` = 未生成，含指针悬空）。 */
	note_path: string | null,
	/**  源正文已变，蒸馏内容不再反映此刻的源。 */
	stale: boolean,
	/**  蒸馏笔记被用户编辑过——自动路径一律止步，重生成必须由用户显式发起。 */
	edited: boolean,
	/**
	 *  已生成的知识笔记不完整时**是哪一道闸到顶**：`caller` / `upstream` / `absolute`
	 *  （[`luna_core::TruncatedBy::key`]）；`null` = 正文自然写完。
	 *
	 *  **不是一个布尔**：三档各对应一个不同的用户动作（ADR-089 ⑧ / PRD-13 §1.5 E）
	 *  ——`caller` 是客户端自己的编译期上限 + 确定性分片，**同一篇再跑必然在同一片撞同一
	 *  道闸**，把它和另外两档一起说成「重新整理」是在请用户白等一遍分钟级的生成；
	 *  `upstream` / `absolute` 换一次候选可能就过去了。压成一句「被截断了」，猜错一次就是
	 *  把人引去改一个改了也没用的设置。归属早已落在产物 frontmatter 里，此前只是没人读。
	 *
	 *  **不叫 `truncated`**：客户端既有的 `truncated`（`chat_session` / `chat.json:52`）
	 *  指的是**输入上下文被裁剪**——同屏两个相反方向的「截断」共用一个名字，读的人一定
	 *  会串。机器口径（协议帧、frontmatter、Fluent key、i18n key）一律走 `output_truncated`
	 *  系，本字段与它们同名同值。
	 */
	output_truncated: string | null,
	/**
	 *  已生成产物所用的模板键（`null` = 未生成或存量产物）。
	 *
	 *  只作**呈现**（徽标 hover 说明「会议纪要式 · 已生成」）。它直接来自已读的目标笔记
	 *  frontmatter，零额外 IO——而「建议模板」要读边车数段落，故**刻意不放这里**：本 DTO
	 *  挂在 `vault://changed` 这条高频路径上，见 [`distill_template_options`]。
	 */
	template: string | null,
};

/**  一个可选模板（前端按 `distill.template.*` / `distill.templateDesc.*` 查文案）。 */
export type DistillTemplateChoiceDto = {
	/**  稳定键（内置 `meeting` / `talk` / …；自定义 `user:<id>`；模板包带来的 `pack:<包>/<id>`）。 */
	id: string,
	/**  自定义与模板包模板的展示名（直接呈现）；`null` = 内置，前端查 i18n。 */
	name: string | null,
	/**  本模板默认是否附整理稿——用户在浮层里换模板时，勾选随之取新模板的默认值。 */
	full_text_default: boolean,
	/**  来自哪个模板包（展示名）；不是包里的为 `null`。 */
	pack_name: string | null,
};

/**  「分发」页签要的东西：有没有脚本、有哪些目标、已经生成过哪些。 */
export type DistributionDto = {
	/**  项目的脚本（没有为 `None`，界面上「从脚本改写」不可选）。 */
	script: string | null,
	/**  按种类排，同种类按项目渠道的顺序。 */
	targets: DistributionTargetDto[],
	outputs: DistributionOutputDto[],
};

/**  已生成的一份超出了目标渠道的上限（序号从 1 起；`max` 是这个渠道的上限）。 */
export type DistributionIssueDto =
/**  第几条帖子太长（`weighted`：这个渠道把中日韩文字算两个，提示里要说明）。 */
{ kind: "post"; post: number; over: number; max: number; weighted: boolean } |
/**  标题（第一个一级标题）太长。 */
{ kind: "title"; over: number; max: number } |
/**  全文太长。 */
{ kind: "body"; over: number; max: number };

/**  分发的种类（顺序即「分发」页签上的顺序）。 */
export type DistributionKindDto = "blog" | "newsletter" | "thread" | "shorts";

/**  已经生成过的一份。 */
export type DistributionOutputDto = {
	kind: DistributionKindDto,
	/**  写给哪个渠道的（通用的一份为 `None`）。 */
	channel: string | null,
	path: string,
	/**  按那个渠道的上限重查的结果（通用的一份不查）。 */
	issues: DistributionIssueDto[],
};

/**  改写的来源：项目的脚本，或项目里的一篇成片转写。 */
export type DistributionSourceDto = { kind: "script" } | { kind: "transcript"; path: string };

/**  分发的一个目标：一种形态，发到项目里的哪个渠道（`None` = 不指定渠道的通用一份）。 */
export type DistributionTargetDto = {
	kind: DistributionKindDto,
	channel: string | null,
};

/**
 *  记录收件箱的一行（PRD-06-058）。
 *  速记侧栏的筛选档（PRD-06-058 A′）。
 *
 *  封闭枚举而不是一段查询串：档位的判据（有没有原声 / AI 补过没有 / 放了多久）全在
 *  Rust，前端交出去的只有「用户点了哪一档」这个入口事实（ADR-003）。
 */
export type DraftFilterDto = "all" | "with_audio" | "refined" | "stale";

/**  记录收件箱一次取齐的结果（PRD-06-058）：列表 + 权威总数 + 汇总限额。 */
export type DraftInboxDto = {
	/**
	 *  全库速记总数（活动栏计数徽标用；**不受列表上限截断，也不受侧栏此刻的筛选影响**）。
	 *
	 *  它与 `matched` 是两个数、都不能省：活动栏角标承诺的是「全库还剩几条」
	 *  （PRD-07-066），一筛选就跟着变的角标是在说谎；侧栏页头要说的则是「这份筛选下有
	 *  几条」，拿全库总数去配一份筛出来的列表同样对不上。
	 */
	total: number,
	/**  当前筛选下的条数（侧栏页头徽标用）。无筛选时与 `total` 相等。 */
	matched: number,
	/**  **这一页**的条目（修改时间倒序）。 */
	notes: DraftNoteDto[],
	/**
	 *  下一页的键集游标；`null` = 已遍历到底（TDD-07 §4.1a）。
	 *
	 *  收件箱的语义是「全部记录态笔记」，不是「最近 N 条」——`total` 说有 700 篇而列表
	 *  只能给出前 N 篇，那个数字就成了摆设。游标不透明，前端只回传。
	 */
	next_cursor: string | null,
	/**
	 *  一次汇总最少要选几条（PRD-06-047）。
	 *
	 *  **常量归 Rust**：前端照着写一份 `>= 2`，就是同一条规则的第二处定义——改了
	 *  一边不会有任何东西变红，而表现只是"按钮说可以、点下去被拒"。
	 */
	merge_min: number,
	/**
	 *  一次汇总最多能选几条（与内核的截断上限同一个常量）。
	 *
	 *  有了它，超限就是**当场被拒**而不是内核静默只取前 N 条——后者会把"我选了 300
	 *  条"悄悄变成一篇只含前 200 条的汇总，且产物里看不出少了什么。
	 */
	merge_max: number,
};

export type DraftNoteDto = {
	/**  笔记相对路径。 */
	path: string,
	/**  标题（= 文件名 stem）。 */
	title: string,
	/**  单行预览（正文首段压成一行）。 */
	preview: string,
	/**  最后修改时间（epoch ms）。TS `number`——时间桶分组与相对时龄都出自它。 */
	modified_ms: number | null,
	/**  它是速记（收件箱原生）还是被标记为记录的普通笔记——行首那枚来源小图标的判据。 */
	quick_note: boolean,
	/**  语音速记已跑过 AI 提炼（PRD-06-058 C′）：行尾挂「已提炼」。 */
	refined: boolean,
	/**  留了原始录音（PRD-02-030）：行首图标改画麦克风，右键给「重新转写」（PRD-02-032）。 */
	has_media: boolean,
	/**  正文里还没勾的待办条数（PRD-06-058 G）；`0` 且 `todo_total` 为 0 = 这篇没有待办。 */
	todo_open: number,
	/**
	 *  正文里的待办总条数。
	 *
	 *  两个数一起下发而不是只给「还剩几条」：用户要读的是进度（`2/5`），而「还剩 2 条」
	 *  在一篇只有两条待办的笔记上与「一条都没做」长得一样。
	 */
	todo_total: number,
	/**
	 *  它此刻钉在桌面上（ADR-119）——右键据此在「钉到桌面 / 取消钉住」之间二选一。
	 *
	 *  下发已判定的布尔而不是那个 frontmatter 键：前端不认识 `luna.desktop_note` 的形状，
	 *  也不该为了一句菜单文案去解析它（ADR-003）。
	 */
	pinned_to_desktop: boolean,
	/**
	 *  原始录音总时长（毫秒；没有录音时为 0）——行上「这条有多长」那一格。
	 *
	 *  零新增存储：`media.duration` 建索引时早就写好，这里只是把既有派生索引里那个数捞
	 *  出来（与转写清单同一个 SQL 表达式）。
	 */
	duration_ms: number | null,
	/**
	 *  它已经**搁置到该催了**（修改时间早于知识体检的陈化门槛，PRD-06-055 同一常量）。
	 *
	 *  下发布尔而不是天数阈值：门槛是 Rust 的判断，前端拿去比一遍就是第二处会漂的
	 *  定义——而两级提醒（行上轻警示 / 体检积压行）必须永远说同一句话。
	 */
	stale: boolean,
	/**
	 *  它能不能参与「多条 → 一篇」（PRD-06-047，判据 `luna_vault::merge_block`）。
	 *
	 *  **对象资格，不是通行证**：它只回答"这个对象够不够格"，不承诺文件此刻可读、
	 *  正文非空，也不承诺点确认时它还是这个样子——`merge_notes` 必须用同一个
	 *  谓词重验一次（用户勾选之后、点确认之前把其中一篇沉淀掉是完全可能的）。
	 */
	can_merge: boolean,
};

export type EditorFlushCancelled = null;

export type EditorFlushRequested = {
	request_id: number,
};

/**  编辑器标签视图模式（PRD-06-010/011/017：Live Preview / 源码 / 阅读）。 */
export type EditorViewModeDto = "live" | "source" | "reading";

/**  一条嵌入 `![[…]]` 指向什么（对标方案 D5）。 */
export type EmbedHitDto =
/**  库里的文件；`link` 是从宿主笔记指向它的相对路径（未转义），按 `![](link)` 渲染。 */
{ kind: "file"; path: string; link: string; image: boolean } |
/**  一篇笔记或其中一节：正文已去 frontmatter，相对链接已按宿主改写。 */
{ kind: "note"; path: string; content: string } | { kind: "missing" };

/**  建库预检 DTO：确认卡据此在**点开始之前**陈述代价。 */
export type EmbedPreflightDto = {
	/**  当前模型（空 = 未配，前端据此给「去下载」引导而不是开始按钮）。 */
	model: string,
	/**  语义检索总开关的真值。 */
	enabled: boolean,
	/**  嵌入能力此刻可用（身份可核实 + profile 基准已过）。 */
	available: boolean,
	/**
	 *  不可用时的**具体原因**（[`EmbeddingReadiness::as_str`] 的稳定 code；可用时为
	 *  `ready`）。前端按它区分「去分配 / 去下载 / 把引擎跑起来」，不合并成一句谎话。
	 */
	readiness: string,
	/**  待嵌入篇数。 */
	pending: number,
	/**  待嵌入的**分片**数（耗时按它估，见 `EmbedScan` 的说明）。 */
	pending_chunks: number,
	/**  已最新的篇数 / 分片数。 */
	fresh: number,
	fresh_chunks: number,
	/**  无可嵌入内容的篇数。 */
	empty: number,
	/**  预估耗时（秒；S16 实测约 0.25 秒/片）。**如实给数字**，不说"很快"。 */
	eta_seconds: number,
	/**  内存矩阵此刻占用的字节数（0 = 还没加载）。 */
	matrix_bytes: number,
	/**  是否已有一次建库在跑。 */
	running: boolean,
};

/**  建库进度事件（`embed://progress`）。逐篇低频（每篇若干次批量嵌入，秒级），无需节流。 */
export type EmbedProgress = {
	/**  已处理篇数（含失败）。 */
	done: number,
	/**  本次总篇数。 */
	total: number,
	/**  已写入的分片数（进度条的第二维：篇数掩盖不了"这一篇有 40 段"这个事实）。 */
	chunks: number,
	/**  失败篇数。 */
	failed: number,
	/**  终态标记。 */
	finished: boolean,
	/**  用户主动取消。 */
	cancelled: boolean,
	/**  连续失败提前中止（引擎不可用的典型指纹）。 */
	halted: boolean,
};

/**  预估的一项消耗。 */
export type EstimateAmountDto =
/**  转写：约多少分钟（向上取整到整分钟——服务端本就按分钟取整计费）。 */
{ unit: "minutes"; minutes: number | null } |
/**  其余计量维度原样（`tokens_in` / `tokens_out` / …）。 */
{ unit: "dimension"; dimension: string; amount: number | null };

/**  这一单会从哪本账扣，或为什么扣不了。 */
export type EstimateOutcomeDto =
/**  订阅额度够：从订阅扣，不动预付。 */
{ state: "subscription" } |
/**  从预付 credits 扣，约这么多。 */
{ state: "prepaid"; credits: number | null } |
/**  不够：在起跑前说清，而不是跑到一半失败。 */
{ state: "insufficient"; reason: EstimateShortfallDto };

/**  不够的原因——两者的下一步不同：额度不够去升级或购买，撞上自设上限去调整上限。 */
export type EstimateShortfallDto = "quota" | "spend_cap";

/**  一次被认出的库外改名。 */
export type ExternalRenameDto = {
	from: string,
	to: string,
	notes: number,
	links: number,
};

/**  当前的库外改名提示。 */
export type ExternalRenamePromptDto = {
	renames: ExternalRenameDto[],
	/**  来自一次批量外部变动（措辞不同：「检测到批量外部变动……」）。 */
	batch: boolean,
	/**  那一阵外部变更的总条数（批量时说给用户听）。 */
	changes: number,
};

/**  库外改名提示变了（有了 / 被修复或忽略）：前端据此重取。 */
export type ExternalRenamesChanged = null;

/**  修复的结果。 */
export type ExternalRepairDto = {
	notes: number,
	links: number,
};

/**  一件外部工具在**本机平台**上的安装引导（`luna_fetch::tool::install_guide` 的投影）。 */
export type ExternalToolGuideDto = {
	/**
	 *  稳定工具 id（`yt_dlp` / `ffmpeg` / `js_runtime`）。前端按它取文案与图标。
	 *
	 *  与 `transcribe.fetch_media` 同一条跨界口径：`luna-fetch` 保持零新增依赖（不引 specta），
	 *  故枚举以**稳定字符串**过界，前端一侧由 `EXTERNAL_TOOLS` 常量 + 守护测试锁住取值集合。
	 */
	tool: string,
	/**  包管理器展示名（`None` = 本平台不给一行命令，只给官方说明页）。 */
	manager: string | null,
	/**  可复制的一行安装命令（`None` 同上）。 */
	command: string | null,
	/**  官方安装说明页（**恒有**）。 */
	docs_url: string,
};

/**  安装计划里的一件组件（`luna_fetch::install::PlannedComponent` 的投影）。 */
export type FetchInstallComponentDto = {
	/**  稳定 id（`yt_dlp` / `js_runtime`，与 `ExternalToolGuideDto::tool` 同一取值空间）。 */
	tool: string,
	/**  本机已有一份 Lunarca 管理的这件组件，这次安装会覆盖它（界面说「重新安装」而不是「安装」）。 */
	replaces_managed: boolean,
	/**  上游来源（仓库地址，不带协议）。 */
	source: string,
	/**  典型下载体积（字节，**约数**；精确值在下载开始后由进度给出）。 */
	approx_download_bytes: number | null,
	/**  典型磁盘占用（字节，约数）。 */
	approx_disk_bytes: number | null,
};

/**
 *  「让 Lunarca 安装」在**点击之前**的完整计划（PRD-05-007 2026-10-08 修订）。
 *
 *  不联网：组件取舍只看本机文件，体积是约数。两个安装入口（「从链接导入」对话框与
 *  「外部工具」面板）都渲染它，并把看过的组件 id 原样交回 `install_fetch_tool` 核对。
 */
export type FetchInstallPlanDto = {
	/**  将要下载的组件（按安装顺序）。 */
	components: FetchInstallComponentDto[],
	/**  安装目录（Lunarca 的私有工具目录；不需要管理员权限、不改系统 PATH）。 */
	install_dir: string,
};

/**  抓取工具可用性快照（前端据此决定给输入框还是给安装引导）。 */
export type FetchToolStatusDto = {
	/**  可以开始抓取（工具找到且能跑，且未被严格本地拦截）。 */
	ready: boolean,
	/**  找到的可执行文件路径（`None` = 未安装；诊断与设置页回显用）。 */
	tool_path: string | null,
	/**  工具自报版本（`None` 而 `tool_path` 在场 = 找到了但跑不起来，两种处境的引导不同）。 */
	version: string | null,
	/**  ffmpeg 是否在场——决定视频档能否取到 1080p（缺失则只能取站点预合并流，通常 ≤720p）。 */
	ffmpeg: boolean,
	/**  ffmpeg 的路径（`None` = 未装）。工具面板显示"装在哪儿"，也是诊断线索。 */
	ffmpeg_path: string | null,
	/**  严格本地模式已开启：抓取被硬拦截（AGENTS.md §7），界面须给"去关闭"而非"去安装"。 */
	strict_local: boolean,
	/**  版本探测**超时**了（≠ 工具坏了）：界面该给「重新检测」而不是「重装」。 */
	probe_timed_out: boolean,
	/**
	 *  **Lunarca 受管安装**的版本（`None` = 未由 Lunarca 装过）。有值即表示"应用管着这份工具"，
	 *  界面据此把主按钮从「安装」切成「更新 / 卸载」（ADR-023 修订）。
	 */
	managed_version: string | null,
	/**
	 *  当前在用的这份是否就是受管那份（用户自己 brew 装的也可能被选中，见发现顺序）。
	 *  界面如实显示"正在使用 Lunarca 管理的 / 系统安装的"，避免"我 brew upgrade 了怎么没变"的困惑。
	 */
	using_managed: boolean,
	/**
	 *  找到的 JS 运行时名（`deno` / `node` / `bun`；`None` = 一个都没装）。
	 *
	 *  缺它**不进 `ready`**：那是降级不是故障（多数站点不需要解 JS 挑战），但 YouTube 这类
	 *  站点的取流会退到不需要挑战的播放器客户端，成功率随站点策略摇摆——故界面要如实标出。
	 */
	js_runtime: string | null,
	/**  该运行时的绝对路径（`None` = 未找到）。与 ffmpeg 同理，面板显示"装在哪儿"。 */
	js_runtime_path: string | null,
	/**
	 *  在用的这份运行时是不是 Lunarca 代装的（决定要不要给「卸载」——77 MB 得给得掉，
	 *  而用户自己装的那份我们绝不去动，与 yt-dlp 同一条纪律）。
	 */
	using_managed_js: boolean,
	/**  Lunarca 代装的那份运行时的版本（`None` = 没代装过，或是本轮之前装的、没记版本）。 */
	managed_js_version: string | null,
	/**  第一次用之前确认过权利声明没有（ADR-167 ④）；没有就先给确认卡。 */
	rights_confirmed: boolean,
};

/**  受管工具的上游更新查询结果（用户点「检查更新」时才联网，见 `check_fetch_tool_update`）。 */
export type FetchToolUpdateDto = {
	/**  上游 latest 的版本 tag（如 `2026.08.19`）。 */
	latest_version: string,
	/**  已装的那份是否落后于它（`false` = 已是最新）。 */
	update_available: boolean,
	/**  受管 JS 运行时（Deno）的检查结果；不是 Lunarca 装的就不查，为 `None`（ADR-167 ⑤）。 */
	js_runtime: ComponentUpdateDto | null,
};

/**  笔记内 AI 悬浮菜单动作。 */
export type FloatingMenuAction =
/**  总结选区（无选区时前端传整篇正文，PRD-06-020）。 */
"summarize" |
/**  翻译选区。 */
"translate" |
/**  优化/润色选区。 */
"optimize" |
/**
 *  自定义指令（Notion "Ask AI" 心智）：按用户输入的指令改写选区/结果，
 *  亦承担结果「追问」（PRD-06-021）——前端以上一轮输出为 text 再次提交。
 */
"ask" |
/**  续写（光标处作用域）：以光标前文为输入，只输出接续的内容（PRD-06-020）。 */
"continue" |
/**  修正拼写 / 语法 / 标点（只改错、不改写；前端据改正稿算逐条差异，PRD-06-021）。 */
"proofread" |
/**  改语气：正式。 */
"tone_formal" |
/**  改语气：轻松。 */
"tone_casual" |
/**  改语气：简洁。 */
"tone_concise" |
/**
 *  把选中的文字整理成一张 GFM 表（对标方案 T6）。Rust 从模型输出里抽出并校验表格，
 *  抽不出就以 `FloatingRejected` 结束、不给落地。
 */
"table_from_text" |
/**  总结 / 解释一张表（作用域 = 这张表的源码），结果插在表格下方。 */
"table_explain" |
/**  按用户的一句指令逐行填写某一列（`options.table_column`），只改这一列。 */
"table_fill_column" |
/**  视频脚本（PRD-19-014）：精简——去掉口水话与重复，说同样的事用更少的字。 */
"script_tighten" |
/**  视频脚本：重写开头——把最抓人的一点放到最前面，不编造事实。 */
"script_hook" |
/**  视频脚本：改成口语——短句、日常用词、直接对观众说。 */
"script_spoken" |
/**  视频脚本（PRD-19-013）：整理口述——去掉口头禅、重复与说错重说，保留本人的话。 */
"script_dictation";

/**  选区前后段落的原样切片（前端只切、不裁；裁剪与拼装在 Rust）。 */
export type FloatingMenuContextDto = {
	before: string,
	after: string,
};

/**
 *  AI 结果的落地方式（PRD-06-021）。Rust 按「动作 × 作用域」给出**建议**，前端把它摆成
 *  主按钮；用户仍可改选其它方式。
 */
export type FloatingMenuLanding =
/**  就地替换选区。 */
"replace" |
/**  插入选区下方。 */
"insert_below" |
/**  插入正文顶部（frontmatter 之后）。 */
"insert_top" |
/**  插入文末。 */
"insert_end" |
/**  插入光标处。 */
"insert_cursor" |
/**  丢弃（只记回执，不动正文）。 */
"discard";

/**  悬浮菜单一轮生成的事实（随 `TranslateEvent::FloatingMenu` 在流首下发）。 */
export type FloatingMenuMeta = {
	/**  建议落地方式（前端主按钮）。 */
	suggested_landing: FloatingMenuLanding,
	/**  这一轮是否交给服务端跑（本机 = `false`）。前端据此标注「本机 · 不联网」或「云」。 */
	on_server: boolean,
	/**  实际送模型的字符数（正文 + 上下文，截断之后）。 */
	sent_chars: number,
	/**  其中上下文（选区前后段落）的字符数；`0` = 没带上下文。 */
	context_chars: number,
	/**  长文分段摘要的分段数（PRD-06-025）；`0` = 直接一轮。 */
	chunks: number,
};

/**  悬浮菜单动作的可选参数（子菜单选择；`None` = 用设置里的默认）。 */
export type FloatingMenuOptionsDto = {
	/**  翻译目标语言（BCP-47 短码）；`None` = 智能双向（设置）。 */
	target_lang: string | null,
	/**  总结风格；`None` = `editor.floating_summary_style`。 */
	summary_style: FloatingSummaryStyle | null,
	/**  「按列填充」填哪一列（0 起）；其它动作不读。 */
	table_column: number | null,
};

/**
 *  后台跑完、**等着用户拍板落地**的一份 AI 结果（PRD-06-021）。
 *
 *  **只存在内存里**，随进程消失：它含笔记正文的产物，落盘既踩脱敏纪律（TDD-12），
 *  又会让一份三天前的结果在重启后突然要求用户处置——而那时它依据的正文多半已经变了。
 */
export type FloatingMenuPendingDto = {
	note_rel: string,
	action: FloatingMenuAction,
	output: string,
	/**
	 *  本轮事实**整份带上**（建议落地 / 执行位置 / 发送字数 / 分段数）：面板呈现待落地
	 *  结果时用的就是它，与前台流首那一份是同一个类型，不为后台另造一套字段。
	 */
	meta: FloatingMenuMeta,
};

/**  预检结果：上限、策略、预计分段数。 */
export type FloatingMenuPreflightDto = {
	limit: number,
	strategy: FloatingMenuStrategy,
	chunks: number,
};

/**
 *  笔记 AI 悬浮菜单作用域（PRD-06-020）：选区 / 光标处 / 整篇。
 *
 *  由前端**如实上报**「用户在哪儿召唤的」，而**怎么处理**（取多少上下文、建议落到哪）
 *  全在 Rust（ADR-003）。
 */
export type FloatingMenuScope =
/**  有选区：动作作用于选区。 */
"selection" |
/**  无选区：作用于光标处（续写 / 起草）。 */
"cursor" |
/**  整篇笔记（页头入口）。 */
"doc";

/**  提交前的长文策略（PRD-06-025：不静默截断，**提交前**就告诉用户会怎么处理）。 */
export type FloatingMenuStrategy =
/**  未超上限，一轮直出。 */
"direct" |
/**  整篇总结超上限：分段摘要后汇总（与蒸馏同一 map-reduce 形态）。 */
"chunked" |
/**  改写类超上限：只处理前 N 字。 */
"truncated" |
/**  光标处生成：只取离光标最近的一段前文。 */
"tail";

/**  用户自定义指令预设（PRD-06-024）的前端投影。 */
export type FloatingPresetDto = {
	id: string,
	name: string,
	instruction: string,
	/**  库里的（可删）还是装上的模板包带来的（随包卸载，ADR-169 ⑤）。 */
	layer: TemplateLayerDto,
	/**  来自哪个模板包（展示名）；库里的为 `None`。 */
	pack_name: string | null,
};

/**  表格 AI 动作的结果为什么不能落地。 */
export type FloatingRejectReason =
/**  模型输出里抽不出一张合法的 GFM 表（「整理为表格」）。 */
"not_a_table" |
/**  作用域不是一张表 / 列号越界（「按列填充」）。 */
"not_a_table_source";

/**  总结风格（PRD-06-020，Notion / Apple 写作工具的「要点 / 段落 / 一句话」）。 */
export type FloatingSummaryStyle = "bullets" | "paragraph" | "one_line";

/**
 *  足迹里的一项：`id` 是稳定码（前端据此取文案），路径与占用是事实，`clearable` 说明
 *  本面板有没有它的清除动作（没有的在文案里指向它自己的入口）。
 */
export type FootprintEntryDto = {
	id: string,
	path: string | null,
	/**  磁盘占用（字节；`f64` 因 specta 无 u64）。`None` = 不适用 / 不存在。 */
	bytes: number | null,
	/**  条目数（回收站条数、凭据条数）。 */
	count: number | null,
	clearable: boolean,
};

/**  一条记录：进了哪一步、什么时刻。 */
export type FunnelMarkDto = {
	/**  步骤 id，或收场标记 [`COMPLETED_MARK`]。 */
	step: string,
	/**
	 *  Unix 毫秒。与 `VaultEntryDto::last_opened_ms` 同一口径（`f64`）——specta 禁止导出
	 *  `i64`（怕精度丢失），而毫秒时刻约 1.8e12，远在 `f64` 的精确整数范围（2^53）之内。
	 *  用绝对时刻而不是相对偏移：本仓的设备级文件本就记绝对时刻，另造一套只会让两份
	 *  记录对不上。
	 */
	at_ms: number | null,
};

/**  全部暂停（ADR-151 ③）。 */
export type GlobalPauseDto = {
	/**  到点自动恢复的时刻（Unix 毫秒）；`None` = 直到用户恢复。 */
	until_ms: number | null,
};

/**  词典批量导入结果（PRD-02 F-GAP-01）。 */
export type GlossaryImportResultDto = {
	/**  新增条数。 */
	imported: number,
	/**  因词条重复/无效被跳过的条数。 */
	skipped: number,
	/**  用户取消了文件选择（前端据此不弹结果提示）。 */
	cancelled: boolean,
};

/**  单条词条落库的结果（`upsert_glossary_entry`）。 */
export type GlossaryUpsertDto = {
	/**  该词条此前已存在，本次是覆盖（`None` = 新增）。 */
	previous: string | null,
};

/**  图谱边 DTO。 */
export type GraphEdgeDto = {
	source: string,
	target: string,
	/**  边类别：`link` / `tag`；主题级网络里恒为 `source`（两页引用了同一篇来源）。 */
	kind: string,
	/**
	 *  关联强度，1–100：主题级网络按 `luna_vault::topic_source_links` 的强度占全图最强一条的
	 *  百分比（画线粗细与布局拉力用，取整数免得前端去猜空值）；笔记级网络恒为 100。
	 */
	strength: number,
};

/**  图谱节点 DTO（`luna_vault::graph::GraphNode` 的前端投影）。 */
export type GraphNodeDto = {
	/**  稳定 id：笔记与主题 = 相对路径；标签 = `tag:<tag>`；幽灵 = `ghost:<目标小写>`。 */
	id: string,
	/**  展示名。 */
	label: string,
	/**  节点类别：`note` / `tag` / `ghost`；主题级网络（`topic_network`）里恒为 `topic`。 */
	kind: string,
	/**  笔记类型串（仅笔记节点，供着色分组）。 */
	note_type: string | null,
	/**
	 *  这一篇是**记录态**吗（ADR-086；标签/幽灵节点恒 `false`）。
	 *
	 *  只是**事实**：记录态「默认隐藏、可开」是前端过滤器区的视图态（与资料的类型
	 *  过滤器同形态，PRD-06-052），构图与索引口径不变——孤立判定仍按全图度数
	 *  （PRD-06-043 同口径）。
	 */
	draft: boolean,
	/**  连接度（节点尺寸映射）。 */
	degree: number,
};

/**
 *  重扫预检 DTO：确认卡据此陈述代价（扫多少篇、跳过多少篇、多少篇被排除规则挡在
 *  范围外）——数字在点开始之前给，而不是开始之后才发现。
 */
export type GraphRescanPreflightDto = {
	/**  指纹已过期（含从未生成）的笔记数——「只补缺口」将扫这些。 */
	stale: number,
	/**  指纹仍最新的笔记数——只有「全部重新生成」会连这些一起重扫。 */
	fresh: number,
	/**  正文为空、无从提炼的笔记数（不参与重扫）。 */
	empty: number,
	/**  **类型白名单外**的篇数（资料区与速记，ADR-024）。这一档是**设计**，用户无须处置。 */
	excluded_type: number,
	/**
	 *  落在**用户停用的文件夹**内的篇数（PRD-06-035c）。
	 *
	 *  与上一档**分开报**（2026-07-30 的 D7）：合成一个"27 篇在排除范围"时，用户无从
	 *  知道其中有 15 篇是**他自己某次误点停用了整个文件夹**——而那一下让整个知识面静默
	 *  失效（标签长不出来 → 主题页建议永不触发 → 归入链路整条够不着，真机连撞三轮）。
	 */
	excluded_folder: number,
	/**
	 *  此刻被停用的文件夹清单（确认卡据此**列出规则本身**并给就地取消）。
	 *
	 *  规则的**结果**可见还不够：只报数字时，用户看得见"被挡住了"却看不见"是什么挡的"，
	 *  更没有入口去改。这一项与 `excluded_folder` 成对存在。
	 */
	excluded_folders: string[],
	/**  是否已有一次重扫在进行中（是则确认卡改呈现进行中状态，不给第二个开始按钮）。 */
	running: boolean,
	/**
	 *  生成此刻**实际**在哪跑：知识管线与对话走同一条 LLM 主干（ADR-001），落点判据同一个
	 *  （ADR-059 ③，与中止通知的 `executed_at` 同源）。确认卡据此陈述执行位置——此前那句
	 *  固定的「生成在本地逐篇进行」在连着服务端时是假话（2026-10-08 文案审查 F02 / C17）。
	 */
	execution: ComputeLocation,
};

/**
 *  重扫进度事件（`graph://rescan`）：逐篇低频（每篇一次 LLM 生成，秒级间隔），
 *  无需节流。终态帧 `finished = true` 且三种收场互斥可辨（跑完 / 取消 / 中止）。
 */
export type GraphRescanProgress = {
	/**  已处理篇数（含失败）。 */
	done: number,
	/**  本次重扫总篇数。 */
	total: number,
	/**  失败篇数（解析失败等单篇故障；不含「另一触发面正在生成」这类良性竞争）。 */
	failed: number,
	/**  重扫范围：`None` = 整个库，`Some(文件夹)` = 定向重扫（进度条据此标注对象）。 */
	scope: string | null,
	/**  终态标记：跑完 / 被取消 / 连续失败中止均置位。 */
	finished: boolean,
	/**  用户主动取消。 */
	cancelled: boolean,
	/**  连续失败提前中止（引擎不可用的典型指纹）——前端据此引导检查 AI 引擎。 */
	halted: boolean,
};

/**  终局 grounding 事实。`None` 仍有语义：本轮未开启库内检索，不被误读为模型回答。 */
export type GroundingOutcome = "grounded_only" | "mixed" | "model_only" | "legacy_unclassified";

/**  中文字形变体（PRD-11-013；映射 `luna_export::HanVariant`）。 */
