export type KnowledgeMetricsExportFormatDto = "json" | "csv";

export type KnowledgeMetricsExportOutcomeDto = "exported" | "cancelled";

/**  Phase 11 的纯聚合投影：没有 token、路径、事件明细或自由文本，前端只负责显示。 */
export type KnowledgeMetricsStatusDto = "ready" | "cleared" | "vault_unavailable" | "keychain_unavailable" | "key_missing" | "invalid_key" | "database_unavailable";

export type KnowledgeNextActionCommand = "create_topic" | "open_checkup" | "rescan_tags" |
/**
 *  重扫并**预选「全部重新生成」档**（PRD-06-035d ①）。与 `RescanTags` 分成两个值
 *  而不是给 DTO 加一个布尔：前端只派发这个穷尽枚举、不按 kind 猜动作（本 DTO 的
 *  既有纪律），而「补缺口」与「全部重来」是两件代价差很远的事——语言分裂的笔记
 *  指纹是最新的，只补缺口一篇都扫不到，等于给一张按下去什么都不发生的卡。
 */
"rescan_tags_force" | "distill_batch" | "resolve_ai_readiness" | "create_knowledge_map" | "resolve_knowledge_map_conflict" | "review_knowledge_map";

export type KnowledgeNextActionDto = {
	suggestion_token: string,
	kind: KnowledgeNextActionKind,
	count: number,
	/**  主动作由 Rust 决定；前端只派发这个穷尽枚举，不再按 kind 猜。 */
	action: KnowledgeNextActionCommand,
	blocker: KnowledgeActionBlocker | null,
	/**  只有修复就绪性时携带精确深链。 */
	target: string | null,
	/**  地图冲突时的候选清单；其它种类恒空。 */
	maps: NoteRefDto[],
	/**  用户接管的地图需要更新时，携带基于当前磁盘正文生成的唯一差异。 */
	map_review: KnowledgeMapReviewDto | null,
	/**  仅主题机会携带；其余候选不让前端反查另一个来源决定动作。 */
	topic: TopicSuggestionDto | null,
	/**  仅「标签语言不一致」携带：出现最多的几条另一种语言的标签（C16）；其余种类恒空。 */
	tags: string[],
};

/**  图谱维护区的唯一推荐类型。排序与可执行性由 Rust 一次决定。 */
export type KnowledgeNextActionKind = "topic_opportunity" | "knowledge_map_missing" | "knowledge_map_conflict" | "knowledge_map_review" | "checkup_finding" |
/**
 *  库内 AI 标签分裂成两种语言（PRD-06-035d ②）。排在 `MissingTags` **之前**：
 *  缺标签只是这一篇没参与进来，而语言分裂会让**每一个**标签的覆盖面减半，
 *  「同标签 ≥3 篇」的主题页判据因此整体失效——它坏掉的是机制，不是单篇。
 */
"tag_language_mismatch" | "missing_tags" | "pending_distill";

/**
 *  知识地图此刻在哪（[PRD-16-023] 的「入口在知识库 → 概览与图谱侧栏」中的前一半）。
 *
 *  **只回答位置，不承担建议**：不存在（还没有主题页）与存在多份（外部操作造出的
 *  冲突态）都返回 `None`——这两种情形各自有自己的闭环，都在图谱维护区那一条排好序的
 *  建议里（「建立知识地图」/「选择保留的知识地图」）。概览这个入口若也去处理它们，
 *  应用就有了第二个维护推荐面，两处排序迟早不一致。
 *
 *  **身份由 frontmatter 判、路径按真实 path 回**：地图是普通 Markdown，用户重命名或
 *  移动之后仍是同一页（PRD-16-023），故前端不得按固定文件名去猜它在哪。
 *  「知识库 → 概览」上半部的**现状**（PRD-07-024a ①）。
 */
export type KnowledgeOverviewDto = {
	/**  知识面的篇数（笔记 + 速记）。 */
	knowledge_notes: number,
	/**  资料区的篇数（录音 + 转写 + 对话）。 */
	materials: number,
	/**
	 *  还没有任何关系（既无链接也无标签）的知识笔记篇数——「图谱稀疏」的用户语言版。
	 *  与体检的孤儿页**同源同数**（判据在 `luna_vault::checkup::classify_connectivity`）。
	 */
	unlinked_notes: number,
	/**  近期活跃标签，按窗口内命中篇数降序。 */
	active_tags: ActiveTagDto[],
	/**  一条值得回看的旧笔记；`None` = 没有够旧的（新库或刚全面整理过）。 */
	revisit: NoteRefLabelDto | null,
};

/**
 *  知识库脉搏的**一次取数**（PRD-16-027 下一步引擎）。仅下行。
 *
 *  三个来源（批量蒸馏预检 / 主题页建议 / 待归入）合成一个命令而不是三次 IPC：脉搏渲染的
 *  是**一个优先级栈的栈顶**，三次往返里任何一次晚到都会让它先渲染一态再跳成另一态。
 */
export type KnowledgePulseDto = {
	/**  批量蒸馏四桶（判据与单篇徽标同源，不另造第二套盘点）。 */
	distill: DistillPreflightDto,
	/**  主题页建议（纯 Rust 零 LLM）。 */
	topics: TopicSuggestionDto[],
};

export type KnowledgeReceiptAction = "open_note";

/**  统一知识回执：只陈述已经落盘或已成功入队的事实。 */
export type KnowledgeReceiptDto = {
	receipt_id: string,
	operation_id: string,
	revision: number,
	kind: KnowledgeReceiptKind,
	outcome: ReceiptOutcome,
	primary_note: NoteRefDto | null,
	updated_topics: NoteRefDto[],
	queued_steps: KnowledgeMaintenanceStep[],
	degraded_steps: KnowledgeMaintenanceStep[],
	primary_action: KnowledgeReceiptAction | null,
	/**
	 *  本次实际写进主题页的条目数；只有逐条确认的计划应用才有。它与目录的「候选来源」、
	 *  预览的「可添加条目」是三个不同的事实，不能互相顶替（TDD-07 §4.1e）。
	 */
	applied_items: number | null,
};

export type KnowledgeReceiptKind = "distill" | "merge" | "topic" | "chat_writeback" | "knowledge_map" | "ingest";

/**  知识库工作台的回访入口：继续阅读 + 近 7 天。 */
export type KnowledgeRecentActivityDto = {
	continue_reading: KnowledgeVisitDto | null,
	week: KnowledgeWeekDto,
};

/**  知识库首页「待你看」：各主题页上等你确认的整理建议，按主题分组（PRD-16-059）。 */
export type KnowledgeReviewInboxDto = {
	groups: ReviewGroupDto[],
	/**  超出上限没列出的主题页数。 */
	omitted: number,
};

/**  「继续阅读」的目标页。 */
export type KnowledgeVisitDto = {
	path: string,
	title: string,
};

/**  知识库首页的「近 7 天」（PRD-16-067 / ADR-136 ⑦）：全部由既有事实确定性派生，不调用模型。 */
export type KnowledgeWeekDto = {
	/**  按「录于何时」收进来的来源篇数，分三类（录音含导入媒体的转写）。 */
	notes: number,
	quick_notes: number,
	recordings: number,
	/**  这 7 天整理出、此刻仍在主题页上的结论数（其中分歧数）。 */
	claims: number,
	conflicts: number,
	/**  新结论最多的至多 5 页；其余只计数。 */
	topics: WeekTopicDto[],
	topics_omitted: number,
	/**  这 7 天收进来、还没被任何主题页引用的来源（新近在前，至多 5 篇）与总数。 */
	unfiled: WeekSourceDto[],
	unfiled_count: number,
};

export type LandingMode = "inject" | "clipboard" | "quick_note";

/**  大文件为什么暂停（ADR-156 ③）。 */
export type LargePauseDto =
/**  按流量计费的网络（手机热点、蜂窝、低数据模式）。 */
"metered" |
/**  低电量模式，或用电池且电量低于 20%。 */
"low_battery";

/**  占着名额的一台设备（界面渲染名称、平台、最近使用）。 */
export type LimitedDeviceDto = {
	id: string,
	name: string,
	/**  `std::env::consts::OS` 口径（同 [`crate::client::DeviceDto::platform`]）；服务端没记为 `null`。 */
	platform: string | null,
	/**  RFC 3339；从没用过为 `null`。本地化在界面层。 */
	last_seen_at: string | null,
};

/**  版本对比结果。 */
export type LineDiffDto = {
	lines: DiffLineDto[],
	added: number,
	removed: number,
	/**  差异区过大已降级为整段替换（对比粒度变粗）。 */
	degraded: boolean,
};

/**
 *  一次**列表语义**的取数（TDD-07 §4.1a）：给了它就是「符合条件的全部条目、可穷尽遍历」。
 *
 *  不给它就是既有的 top-N 语义。全文检索路径**不接受**它（相关度序做不出稳定游标），
 *  带着它去查全文会拿到 `LIST_CURSOR_INVALID`。
 */
export type ListPageDto = {
	sort: ListSortDto,
	/**  上一页末行的 `cursor` 原样回传；`null` = 第一页。**不解析、不自行构造**。 */
	cursor: string | null,
};

/**  列表排序键（TDD-07 §4.1a）。前端只回选中的这一个键，排序在 SQL 层完成。 */
export type ListSortDto =
/**  最近修改在前。 */
"modified" |
/**
 *  标题 **UTF-8 码点序**——与旧版前端 `localeCompare` 不同，中文标题的先后会变
 *  （`luna_vault::ListSort::Name` 写着为什么必须是它）。
 */
"name" |
/**  时长（长的在前）。 */
"duration" |
/**  「录于何时」倒序（没记创建时间的老笔记退到修改时间，PRD-07-007）。 */
"created";

/**  一条能力在服务端路径上的本机候选及下一步动作（ADR-038 / ADR-085）。 */
export type LocalCandidateDto = {
	/**  `chat` / `embedding` / `transcription`。与 [`ComputeRouteDto`] 共用稳定能力名。 */
	capability: string,
	/**  自动兜底或显式选择的边界。 */
	policy: LocalCandidatePolicy,
	/**  已解析的本机候选展示名；没有候选时为空，绝不打印内部 target id。 */
	model_name: string | null,
	/**  真实就绪结论及不可用原因。 */
	readiness: LocalCandidateReadiness,
	/**  仅转写候选有意义：它是否为随包 tiny；其他能力恒为 `false`。 */
	is_minimal: boolean,
	/**  本条能力的模型设置入口；嵌入也只允许从这里显式配置。 */
	setting_key: string,
};

/**
 *  服务端路径上的本机候选如何参与执行。
 *
 *  这不是「是否可重试」的另一种说法：它投影的是 `JobError::failover_disposition` 的
 *  用户可见边界。只有链路不可达时，文本/转写才会在首个可见输出前换到本机；嵌入的
 *  向量空间是索引身份，绝不能把一次云端请求悄悄改写成本地索引结果。
 */
export type LocalCandidatePolicy =
/**  `ProviderUnavailable` / `Timeout` 且尚无可见输出时，允许从服务端切到本机。 */
"unreachable_before_visible_output" |
/**  该能力只接受显式选择；不在服务端失败时自动改写执行位置。 */
"explicit_only";

/**  本机候选的实际就绪结论。前端只渲染此枚举，不由模型名或 Provider 前缀反推。 */
export type LocalCandidateReadiness = "ready" | "model_missing" | "runtime_unavailable" | "not_applicable";

/**  最近一次故障的类别（只有类别，没有日志原文——日志可能含请求片段）。 */
export type LocalEngineFailure =
/**  拉不起来（文件缺失 / 权限）。 */
"spawn" |
/**  规定时间内没有就绪。 */
"start_timeout" |
/**  进程退出。 */
"exited" |
/**  进程挂起、健康探针不通。 */
"unresponsive" |
/**  计算后端（Metal）报错。 */
"compute_error" |
/**  模型文件损坏或不完整。 */
"corrupt_model" |
/**  参数被引擎拒绝。 */
"bad_arguments";

/**  一个进了引擎的模型。 */
export type LocalEngineModelDto = {
	/**  目录条目 id。 */
	model_id: string,
	/**  展示名。 */
	name: string,
	/**  定下的上下文（token）。 */
	context_tokens: number,
	/**  KV 类型（`f16` / `q8_0`）。 */
	kv_type: string,
	/**  走了退让档：内存不够全量，KV 改了 q8_0 或上下文被减。 */
	degraded: boolean,
};

/**  一个因内存没进引擎的模型（启动前预检拒绝，ADR-143 ④）。 */
export type LocalEngineRefusalDto = {
	/**  目录条目 id。 */
	model_id: string,
	/**  展示名。 */
	name: string,
	/**  最小参数下仍需要的内存（字节）；估不出来时为空。以 f64 表达供 JS number 消费。 */
	need_bytes: number | null,
	/**  当时可给的额度（字节，已扣余量与先排定的模型）；估不出来时为空。 */
	budget_bytes: number | null,
};

/**  引擎所处的状态（界面文案按它分支）。 */
export type LocalEngineState =
/**  没在跑：还没有需要它的本地模型，或已停止。 */
"stopped" |
/**  正在拉起。 */
"starting" |
/**  就绪。 */
"ready" |
/**  意外退出，正在按退避重启。 */
"restarting" |
/**  连续失败已熔断，等用户手动重启。 */
"tripped";

/**
 *  「本地推理引擎状态可能变了」（`local-engine://changed`）：监管器状态变化、编排完成时发；
 *  前端收到后重取 [`local_engine_status`]。
 */
export type LocalEngineStatusChanged = Record<string, never>;

/**  本地推理引擎状态。 */
export type LocalEngineStatusDto = {
	/**  本平台是否随包了引擎、且文件齐全。`false` 时其余字段无意义。 */
	runtime_present: boolean,
	/**  本构建是否启用 GGUF 模型（目录条目与导入入口）；关着时界面不露出本地推理相关的一切。 */
	gguf_enabled: boolean,
	/**  引擎构建号（如 `b11429`）。 */
	engine_build: string | null,
	/**  状态。 */
	state: LocalEngineState,
	/**  重启中时：已连续失败次数。 */
	failures: number,
	/**  最近一次故障类别。 */
	last_failure: LocalEngineFailure | null,
	/**  进了引擎的模型（按加载优先级）。 */
	models: LocalEngineModelDto[],
	/**  因内存没进引擎的模型。 */
	refused: LocalEngineRefusalDto[],
};

